# Essential imports (guaranteed to be available)
import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import torch.optim as optim
from dataset import get_dataloader
import json
from tqdm import tqdm
import numpy as np
from sklearn.metrics import roc_auc_score


# Data Ingestion
DATA_DIR = "/mnt/disks/data/birdclef"
METADATA_FILE = os.path.join(DATA_DIR, "train.csv")
iteration = 1  # Example iteration number

# Hyperparameter selection based on the current iteration
batch_size_options = {0: 8, 1: 16, 2: 32}
lr_options = {0: 0.001, 1: 0.0001, 2: 0.00001}
conv_layers_options = {0: 2, 1: 3, 2: 4}

batch_size = batch_size_options[iteration % 3]
lr = lr_options[iteration % 3]
num_conv_layers = conv_layers_options[iteration % 3]

# Model Architecture
class BirdCLEFModel(nn.Module):
    def __init__(self, num_classes=234, dropout_rate=0.5):
        super(BirdCLEFModel, self).__init__()
        layers = []
        in_channels = 1
        for i in range(num_conv_layers):
            out_channels = 32 * (2 ** i)
            layers.extend([
                nn.Conv2d(in_channels, out_channels, kernel_size=3, padding=1),
                nn.BatchNorm2d(out_channels),
                nn.ReLU(),
            ])
            in_channels = out_channels
        self.conv_layers = nn.Sequential(*layers)
        self.pool = nn.AdaptiveAvgPool2d((1, 1))
        self.classifier = nn.Sequential(
            nn.Dropout(dropout_rate),
            nn.Linear(in_channels, 128),
            nn.ReLU(),
            nn.Linear(128, num_classes)
        )

    def forward(self, x):
        x = self.conv_layers(x)
        x = self.pool(x).view(x.size(0), -1)
        return torch.sigmoid(self.classifier(x))

# Initialize model, optimizer and loss function
device = torch.device('cuda' if torch.cuda.is_available() else 'cpu')
model = BirdCLEFModel().to(device)
optimizer = optim.Adam(model.parameters(), lr=lr, weight_decay=0.001)  # L2 regularization
criterion = nn.BCELoss()

# Data Loaders
train_loader = get_dataloader(DATA_DIR, METADATA_FILE, batch_size=batch_size)

# Training Loop
num_epochs = 2
model.train()
final_train_loss = None

for epoch in range(num_epochs):
    epoch_loss = 0.0
    batch_count = 0
    for inputs, labels in train_loader:
        if batch_count >= 5000 // batch_size:  # Limit to ~5000 samples
            break
        optimizer.zero_grad()
        
        inputs, labels = inputs.to(device), labels.float().to(device)
        outputs = model(inputs)
        loss = criterion(outputs, labels)
        
        loss.backward()
        optimizer.step()
        
        epoch_loss += loss.item()
        batch_count += 1
    
    final_train_loss = epoch_loss / batch_count
    print(f'Epoch [{epoch+1}/{num_epochs}], Loss: {final_train_loss:.4f}')
    
    torch.cuda.empty_cache()

# Evaluation Loop
model.eval()
all_preds = []
all_labels = []

with torch.no_grad():
    for inputs, labels in train_loader:
        if batch_count >= 5000 // batch_size:  # Use the same ~5000 samples for validation
            break
        
        inputs, labels = inputs.to(device), labels.float().to(device)
        outputs = model(inputs)
        
        all_preds.append(outputs.cpu().numpy())
        all_labels.append(labels.cpu().numpy())
        batch_count += 1

all_preds = np.concatenate(all_preds)
all_labels = np.concatenate(all_labels)

# Calculate Validation AUC
final_auc = roc_auc_score(all_labels, all_preds, average='weighted')

# Save Metrics
num_params = sum(p.numel() for p in model.parameters() if p.requires_grad)
metrics = {
    "final_train_loss": final_train_loss,
    "final_auc": final_auc,
    "num_params": num_params,
    "epochs_trained": num_epochs,
    "batch_size": batch_size,
    "training_samples": 5000,
    "eval_samples": 5000
}

with open('metrics.json', 'w') as f:
    json.dump(metrics, f)

# Save Model Checkpoint
